ine Pertumbuhan</h2><span class="muted">{{ $selected->monitorings->where('status','approved')->count() }} laporan</span></div><div class="timeline">@foreach($selected->monitorings->where('status','approved') as $log)<article class="timeline-card"><div class="summary-line"><strong>{{ $log->observed_at->format('d M Y') }}</strong><x-badge :status="$log->health"/></div><p>Tinggi {{ $log->height }} cm</p><p>{{ $log->care_note }}</p><a href="{{ route('files',['type'=>'monitoring','id'=>$log->id]) }}" target="_blank" rel="noopener"><img class="report-photo" src="{{ route('files',['type'=>'monitoring','id'=>$log->id]) }}" alt="Foto monitoring {{ $log->observed_at->format('d M Y') }}"></a></article>@endforeach @if($selected->planting?->status==='approved')<article class="timeline-card"><div class="summary-line"><strong>{{ $selected->planting->planted_at->format('d M Y') }}</strong><span class="badge badge-green">Penanaman awal</span></div><img class="report-photo" src="{{ route('files',['type'=>'planting','id'=>$selected->planting->id]) }}" alt="Bukti tanam terverifikasi"></article>@else<div class="info-box">Menunggu penanaman oleh Mitra atau verifikasi bukti oleh Admin.</div>@endif</div><section class="panel"><h3>Pilih Pohon</h3>@foreach($trees as $tree)<a class="tree-select {{ $selected->id===$tree->id?'selected':'' }}" href="/trees?tree={{ $tree->id }}">{{ $tree->item->offer->species }}<small>{{ $tree->code }}</small></a>@endforeach</section>@else<section class="panel"><x-empty title="Belum ada pohon adopsi" text="Setelah pembayaran berhasil, identitas pohon akan muncul di sini."/><a class="button w-full" href="{{ route('donor.catalog') }}">Jelajahi Katalog</a></section>@endif</aside></div>
